def norm(x):return re.sub(r'[^a-z0-9]','',unicodedata.normalize('NFKD',x).encode('ascii','ignore').decode().lower())
for form,title,source,basis in items:
 u='https://api.openalex.org/works';r=requests.get(u,params={'search':title,'per-page':8},timeout=25);r.raise_for_status();data=r.json();receipts.append({'url':r.url,'retrieved_utc':t,'status':r.status_code,'body':data});n=norm(title);matches=[x for x in data['results'] if norm(x['title'])==n or (len(n)>30 and (norm(x['title']).startswith(n) or n.startswith(norm(x['title']))))];
 if not matches:print('NO MATCH',title,[x['title'] for x in data['results'][:3]]);continue
